export type AlertDialogProps = {
  /** The caller's state. */
  open: boolean;
  /** Called by Cancel and by Escape. Ignored while `pending`. */
  onClose: () => void;
  /** Called by the confirm button. The caller does the act and closes. */
  onConfirm: () => void;
  /** The question, with the object in it: "Archive this program?" */
  title: ReactNode;
  /** What happens, in one or two sentences: what is kept, what cannot be undone. */
  description?: ReactNode;
  /** The verb, as the button that started it: Archive, Submit, Delete. Never OK or Yes. */
  confirmLabel?: string | undefined;
  cancelLabel?: string | undefined;
  /** `danger` when the act removes, closes or cannot be undone; the button turns red. */
  tone?: "primary" | "danger" | undefined;
  /** Holds the dialog open with the confirm button busy while the caller saves. */
  pending?: boolean | undefined;
  /** Under the description: one control the decision needs, a Checkbox or a Field. */
  children?: ReactNode;
};

export type AlertProps = {
  /** The status the message carries: it sets the fill, the text and the Dot. `warning` is the default. */
  tone?: Tone | undefined;
  /** One line in the tone's colour after the Dot: what is wrong or what changed. Omit it for a one-sentence note. */
  title?: ReactNode;
  /** The body, one or two sentences: what it means and what to do. */
  children?: ReactNode;
  /** The one thing that resolves it, under the body: a TextLink or a link Button, drawn in the alert's own colour and underlined, as the Banner draws its action. */
  action?: ReactElement<{ className?: string | undefined }> | undefined;
  className?: string | undefined;
};

export type AvatarProps = {
  /** The person's full name. The initials, the hue and the accessible name come from it. */
  name: string;
  /** A photo. It fills the circle; the initials return if it fails to load. */
  src?: string | undefined;
  /** `xsmall` is 16px and one initial, beside a name; `small` is 24px, the default, alone in a header or a stack; `medium` is 32px, in a comment or a card; `large` is 40px, in a profile row; `xlarge` is 64px, on a profile page. */
  size?: AvatarSize | undefined;
  /** `neutral`, the default, is the grey mark: a person never reads as a status. `tinted`, `bold` and `gradient` take a hue from the name, stable per person, from the accent colours, which carry no meaning. */
  variant?: AvatarVariant | undefined;
  /** Pins the hue instead of drawing it from the name: a system's mark, a team's colour. */
  hue?: AvatarHue | undefined;
  /** `circle` for a person, the default; `square` for a thing: a system, a program, a team. */
  shape?: "circle" | "square" | undefined;
  /** The name is written beside it (Person) or the group is named (Avatar.Stack): hide the avatar from a screen reader so the name is read once. */
  isDecorative?: boolean | undefined;
  className?: string | undefined;
  style?: CSSProperties | undefined;
};

export type PersonProps = {
  /** The person's full name, written beside the avatar. */
  name: string;
  /** The person's photo, if there is one. */
  src?: string | undefined;
  /** The avatar's colour treatment; `neutral` by default. */
  variant?: AvatarVariant | undefined;
  className?: string | undefined;
};

export type AvatarStackProps = {
  /** The people, in order. The group is named by all of them. */
  names: AvatarStackPerson[];
  /** How many avatars to show before the rest fold into a +n, 4 by default. */
  max?: number | undefined;
  /** `small` is 24px, the default; `medium` is 32px, on a profile or a card. */
  size?: "small" | "medium" | undefined;
  /** The colour treatment of every circle; `neutral` by default. */
  variant?: AvatarVariant | undefined;
};

export type BadgeProps = {
  /** The status the word carries, from the tone table. `neutral` is the default, and a category or a kind is always neutral. */
  tone?: Tone | undefined;
  /** `subtle` is the tinted fill with the tone's text; `bold` is the solid fill for the one status that must win. */
  appearance?: "subtle" | "bold";
  /** `small` is 20px, the default; `xsmall` is 16px, for a table row or a tab. */
  size?: keyof typeof badgeSizes;
  /** A 12px icon before the word, rarely: when the word alone is ambiguous. */
  icon?: ReactNode;
  /** One or two words in sentence case: the state. */
  children: ReactNode;
  className?: string | undefined;
} & Omit<ComponentPropsWithoutRef<"span">, "children" | "className">;

export type CountProps = {
  /** The number. Anything above `max` renders as `max+`; a string renders as given. */
  value: number | string;
  /** The ceiling, 99 by default: the pill never grows past three characters and a plus. */
  max?: number;
  /** `default` is the neutral pill; `primary` the brand fill for the one count that must be seen; `important` the danger fill for what needs attention now; `added` and `removed` for a diff. */
  appearance?: keyof typeof countAppearances;
  className?: string | undefined;
} & Omit<ComponentPropsWithoutRef<"span">, "children" | "className">;

export type DotProps = {
  tone?: Tone | undefined;
  /** What the dot says when no text sits beside it: the status as a word ("Suspect", "No supplier attestation on file"). With it the dot is an image named by the label; without it the dot is hidden and the text beside it carries the status. */
  label?: string | undefined;
  className?: string | undefined;
};

export type IndicatorProps = {
  /** The severity or the health the Dot carries. `neutral` mutes the text as well: the lowest rung. */
  tone?: Tone | undefined;
  /** The word beside the Dot: "High", "Healthy", "Obligation not stated". It truncates when the row is narrower than it. */
  children: ReactNode;
  className?: string | undefined;
} & Omit<ComponentPropsWithoutRef<"span">, "children" | "className">;

export type BannerProps = {
  /** `information` for something that changed, `warning` for something about to, `danger` for something lost. `warning` is the default; there is no success banner. */
  tone?: BannerTone | undefined;
  /** Replaces the tone's icon. */
  icon?: ComponentType<{ className?: string | undefined }> | undefined;
  /** One link or button, rendered in the banner's own colour: an anchor, a button, or the router's Link. */
  action?: ReactElement<{ className?: string | undefined }> | undefined;
  className?: string | undefined;
  /** The message, one line. It truncates rather than wraps. */
  children: ReactNode;
};

export type BreadcrumbProps = {
  /** Breadcrumb.Item children, from the highest level down to the page. */
  children: ReactNode;
  /** The landmark's name, "Breadcrumb" by default. A second trail on the page, a chart's drill-down path, takes its own: "Chart path". */
  label?: string | undefined;
  className?: string | undefined;
};

export type BreadcrumbItemProps = {
  /** The page itself: not a link, reads in the default colour, and `aria-current="page"`. */
  isCurrent?: boolean | undefined;
  /** The child (a router's Link) takes the item's classes. Without it the item is a button, for a crumb that changes state in place. */
  asChild?: boolean | undefined;
  /** The record's name as its title reads, or the level's name: "Programs", "Atlas payments platform". */
  children: ReactNode;
  className?: string | undefined;
} & Omit<ComponentPropsWithoutRef<"button">, "children" | "className">;

export type ButtonGroupProps = {
  /** The group's name, when it is not clear from the buttons: "Export", "Approve". */
  label?: string | undefined;
  /** Buttons or IconButtons of one size and one variant. Two or three; a fourth is a menu. */
  children: ReactNode;
  className?: string | undefined;
};

export type ButtonProps = {
  ref?: Ref<HTMLButtonElement>;
  /** The emphasis. `secondary` is the default; at most one `primary` per view. */
  variant?: ButtonVariant | undefined;
  /** `medium` (32px) for forms and pages, `small` (28px) for toolbars, rows and rails, `xsmall` (24px) for the densest chrome. `link` has no size. */
  size?: ButtonSize | undefined;
  /** An icon before the label. Pass the element bare; the button sizes it. */
  iconBefore?: ReactElement | undefined;
  /** An icon after the label: a chevron for a menu, an arrow for a step. Pass the element bare. */
  iconAfter?: ReactElement | undefined;
  /** The action is in flight: a spinner takes the icon's place, the label stays, clicks are ignored and focus is kept. */
  isLoading?: boolean | undefined;
  /** The button is the current choice: a filter applied, a view chosen. Sets `aria-pressed` and paints the selected role. */
  isSelected?: boolean | undefined;
  /** Fills the container: a sheet's footer, a narrow form. */
  isFullWidth?: boolean | undefined;
  /** Render the child element instead of a `<button>`, keeping the button's classes. This is how a router's Link becomes a button. */
  asChild?: boolean | undefined;
  children?: ReactNode;
  className?: string | undefined;
} & Omit<ComponentPropsWithoutRef<"button">, "children" | "className">;

export type IconButtonProps = {
  ref?: Ref<HTMLButtonElement>;
  /** The accessible name and the tooltip. Required: the icon has no text. */
  label: string;
  /** The icon, passed bare; the button sizes it. */
  icon: ReactElement;
  /** `secondary` is the raised button; `subtle` sits in toolbars and rows; `primary` is the bold fill, for the chevron of a primary split button. */
  variant?: "primary" | "secondary" | "subtle" | undefined;
  /** `small` (28px) is the default, for toolbars and rows; `medium` (32px) sits beside medium controls. */
  size?: "small" | "medium" | undefined;
  /** Hides the tooltip where the label is already visible beside the button. The accessible name stays. */
  isTooltipDisabled?: boolean | undefined;
  /** The action is in flight: a spinner takes the icon's place, clicks are ignored and focus is kept. */
  isLoading?: boolean | undefined;
  /** The button is the current choice. Sets `aria-pressed` and paints the selected role. */
  isSelected?: boolean | undefined;
  /** Render the child element instead of a `<button>`, keeping the classes; the icon goes inside it. */
  asChild?: boolean | undefined;
  children?: ReactNode;
  className?: string | undefined;
} & Omit<ComponentPropsWithoutRef<"button">, "children" | "className" | "aria-label">;

export type ChartBarProps = {
  /** Plain records, in the order they are drawn. */
  data: ChartDatum[];
  /** The key that names each datum along the category axis. */
  x: string;
  /** One entry per value key. A series' own `format` wins over the plot's. */
  series: ChartSeries[];
  /** Stack the series in one bar per category, parts of a whole. */
  stacked?: boolean | undefined;
  /** Categories down the side, values across: for long names, or many categories. */
  horizontal?: boolean | undefined;
  /** `end` prints each bar's value at its end. For a chart with a few bars and no stacking. */
  labels?: "none" | "end" | undefined;
  /** A key in each datum holding a target: drawn as a mark across the bar, so actual reads against planned. */
  target?: string | undefined;
  /** A series drawn as a line over the bars on the same axis: a cumulative, a rate, a plan. */
  line?: ChartSeries | undefined;
  /** The value axis' ends, to share a scale across charts. `[0, "auto"]` when unsaid; a value below zero extends the axis below it and draws the zero line. */
  domain?: ChartDomain | undefined;
  /** Titles for the axes, when the keys and the Frame's title do not say enough: the unit on the value axis. */
  xLabel?: string | undefined;
  yLabel?: string | undefined;
  /** Every series wears a pattern as well as its colour, so a stack reads in print and under colour-vision loss. The Frame's `texture` sets it for the legend too. */
  texture?: boolean | undefined;
  /** Charts with the same id share their hover. The Frame's `syncId` sets it. */
  syncId?: string | undefined;
  /** The plot's height. `medium` (200px) when unsaid. */
  size?: ChartSize | undefined;
  /** A height in pixels when a layout must, in place of `size`. */
  height?: number | undefined;
  /** The number format for the value axis, the tooltip and the labels. The Frame's, else the kit's. */
  format?: Formatter | undefined;
  /** The format for a category: a date, a code. */
  formatX?: CategoryFormatter | undefined;
  /** Lines across the plot: a target, a limit, a milestone. */
  reference?: ChartReference[] | undefined;
  /** The plot's accessible name. Unneeded inside a Frame, which names it after its title; a plot with neither is hidden from a screen reader. */
  label?: string | undefined;
  /** Draws the plot's skeleton in place of the marks. The Frame sets it from `status="loading"`. */
  loading?: boolean | undefined;
  /** Called when a bar is clicked, or Enter chooses the focused category: to drill down, or to filter what is under the chart. */
  onSelect?: ((selection: ChartSelection) => void) | undefined;
  /** More about what was chosen, in a card anchored to it: facts, a link to the record. The card's head (the category, the series, the value) is the kit's. */
  details?: ((selection: ChartSelection) => ReactNode) | undefined;
  className?: string | undefined;
};

export type ChartDonutProps = {
  /** The parts, in order from the top, clockwise. */
  slices: DonutSlice[];
  /** The number in the middle: the total, the share, the one that matters. */
  label?: ReactNode | undefined;
  /** One word under the number: what it counts. */
  caption?: string | undefined;
  /** `full` is a ring; `half` is a gauge, open at the bottom, the label at its base. */
  arc?: "full" | "half" | undefined;
  /** Diameter in pixels. */
  size?: number | undefined;
  /** The ring's thickness in pixels. */
  thickness?: number | undefined;
  /** The number format in the tooltip. */
  format?: Formatter | undefined;
  /** The ring's accessible name. Unneeded inside a Frame. */
  name?: string | undefined;
  /** Every slice wears a pattern as well as its colour. The Frame's `texture` sets it. */
  texture?: boolean | undefined;
  /** Draws the ring's skeleton in place of the slices. The Frame sets it from `status="loading"`. */
  loading?: boolean | undefined;
  /** Called when a slice is clicked. */
  onSelect?: ((selection: DonutSelection) => void) | undefined;
  /** More about the chosen slice, in a card anchored to it. The card's head (the slice, its value and its share) is the kit's. */
  details?: ((selection: DonutSelection) => ReactNode) | undefined;
  className?: string | undefined;
};

export type ChartLegendProps = {
  series: ChartSeries[];
  /** A square for bars and areas, a stroke for lines, a dot for points. */
  swatch?: SwatchShape | undefined;
  /** The swatches carry each series' pattern. The Frame's `texture` sets it. */
  texture?: boolean | undefined;
  className?: string | undefined;
};

export type ChartFrameProps = {
  /** What the chart shows, as a noun phrase: "Coverage by control family". It names the plot to a screen reader. */
  title: string;
  /** One line under the title: the period, the unit, the source. */
  description?: ReactNode | undefined;
  /** One sentence for a screen reader that says what the chart shows: "Open findings fell from 14 in January to 5 in September." The figure's description. Not shown. */
  summary?: string | undefined;
  /** The levels drilled into so far, from the top: `[{ label: "All families", onSelect }, { label: "AC" }]`. A Breadcrumb under the title; every crumb but the last goes back. */
  path?: ChartCrumb[] | undefined;
  /** The series, for the legend and the table. */
  series?: ChartSeries[] | undefined;
  /** Where the legend sits. `top` when there are two or more series, `none` for one: the title names it. At a narrow width the header wraps and the legend drops under the title. */
  legend?: "top" | "bottom" | "none" | undefined;
  /** The legend's swatch: a square for bars and areas, a stroke for lines, a dot for points. */
  swatch?: SwatchShape | undefined;
  /** Every series wears a pattern as well as its colour, in the plot and in the legend: for print, colour-vision loss and forced colours. */
  texture?: boolean | undefined;
  /** Charts with the same id share their hover: the tooltip moves on all of them. For small multiples. */
  syncId?: string | undefined;
  /** Controls at the end of the header: a range, a filter, a Retry. */
  actions?: ReactNode | undefined;
  /** The files the reader can take away, as a Download menu in the header: the table twin as CSV (needs `data` and `x`), the plot as a PNG at twice the pixel density. */
  download?: ("csv" | "png")[] | undefined;
  /** An Expand button in the header that opens the same chart in a large Dialog. */
  expandable?: boolean | undefined;
  /** `loading` draws the plot's skeleton at its height; `refreshing` keeps the last plot, dimmed, with a spinner in the header; `empty` and `error` say so in the plot's place. */
  status?: "ready" | "loading" | "refreshing" | "empty" | "error" | undefined;
  /** What an empty or failed plot says. "Nothing to show yet" and "The chart could not load" when unsaid. */
  statusTitle?: string | undefined;
  statusText?: string | undefined;
  /** The records and the category key, so the Frame can lay the same numbers out as a Table, one toggle away, and as a CSV. */
  data?: ChartDatum[] | undefined;
  x?: string | undefined;
  /** What the table calls the category column: "Month", "Family". The key when unsaid. */
  xLabel?: string | undefined;
  /** Columns for the table twin and the CSV beyond the series, each a key in the datum: a name beside the category (`place: "before"`), a total, a share, an owner after the series. Facts the plot does not draw, so the twin is the record's table and not only the plot's. */
  columns?: ChartColumn[] | undefined;
  /** The number format the plot, the tooltip and the table share. */
  format?: Formatter | undefined;
  formatX?: CategoryFormatter | undefined;
  /** The plot's height, for the states that stand in for it. */
  size?: ChartSize | undefined;
  height?: number | undefined;
  /** The plot. */
  children: ReactNode;
  className?: string | undefined;
};

export type ChartHeatmapProps = {
  /** The row names, top to bottom. */
  rows: string[];
  /** The column names, left to right. */
  columns: string[];
  /** The value at a row and column. `undefined` or `null` leaves the cell empty. */
  value: (row: string, column: string) => number | null | undefined;
  /** `sequential` paints how much in one hue; `diverging` paints above and below `midpoint` in two; a function says which status tone a cell carries, from its value or its row and column, and the cell prints its value. */
  scale?: HeatmapScale | undefined;
  /** The values at the ends of the scale. The data's own when unsaid. */
  domain?: readonly [number, number] | undefined;
  /** The value that reads as nothing on a diverging scale. Zero when unsaid. */
  midpoint?: number | undefined;
  /** Print the value in each cell. On for a status scale, where the tone's fill carries its text; off for a colour scale, where the tooltip and the table carry it, and where a printed value sits on a surface chip. */
  showValues?: boolean | undefined;
  /** The cell's height: `small` 24px, `medium` 32px, `large` 40px. */
  size?: ChartSize | undefined;
  format?: Formatter | undefined;
  /** The grid's accessible name. It is a table. */
  label: string;
  /** What the rows and the columns are: the corner cell, and the description a screen reader hears. */
  rowLabel?: string | undefined;
  columnLabel?: string | undefined;
  /** Draws skeleton cells in place of the values. The Frame does not set it: a grid's shape is its own. */
  loading?: boolean | undefined;
  /** Makes the cells buttons: called when one is clicked or chosen with Enter. */
  onSelect?: ((selection: HeatmapSelection) => void) | undefined;
  /** More about the chosen cell, in a card anchored to it. The card's head (the row, the column and the value) is the kit's. */
  details?: ((selection: HeatmapSelection) => ReactNode) | undefined;
  className?: string | undefined;
};

export type ChartScaleProps = {
  /** Which ramp the key shows. */
  scale: "sequential" | "diverging";
  /** What the low end and the high end read as: "0" and "40 findings"; "−20%" and "+20%". */
  min: string;
  max: string;
  /** The midpoint's word on a diverging scale: "On plan". */
  mid?: string | undefined;
  className?: string | undefined;
};

export type ChartLineProps = {
  /** Plain records, in the order they are drawn. */
  data: ChartDatum[];
  /** The key that names each datum along the category axis: a label, or a Date on a time axis. */
  x: string;
  /** One entry per value key. A series' own `format` wins over the plot's. */
  series: ChartSeries[];
  /** `category` spaces the points evenly and prints their labels; `time` reads `x` as dates, spaces the points by time, and picks the ticks by the span: hours, days, months or years. */
  scale?: "category" | "time" | undefined;
  /** `linear` joins the points; `smooth` eases between them without overshooting. */
  curve?: "linear" | "smooth" | undefined;
  /** A marker on every point, for a series with few points. Hover shows one either way. */
  dots?: boolean | undefined;
  /** `end` prints each series' last value after its line. */
  labels?: "none" | "end" | undefined;
  /** `zero` starts the value axis at zero; `auto` crops to the data, for a trend where the change matters more than the size. */
  baseline?: "zero" | "auto" | undefined;
  /** The value axis' ends, to share a scale across charts; wins over `baseline`. A value below zero extends the axis and draws the zero line. */
  domain?: ChartDomain | undefined;
  /** Bands across the plot: between two values (the acceptable range) or two categories or dates (an assessment window). */
  bands?: ChartBand[] | undefined;
  /** Join across a missing value. Off, a gap says the data was not there. */
  connectNulls?: boolean | undefined;
  /** Print each series' change from the point before in the tooltip and the card: "+3". */
  delta?: boolean | undefined;
  /** Titles for the axes, when the keys and the Frame's title do not say enough: the unit on the value axis. */
  xLabel?: string | undefined;
  yLabel?: string | undefined;
  /** Every series wears a pattern in its wash as well as its colour (an Area; a Line's stroke stays solid). The Frame's `texture` sets it. */
  texture?: boolean | undefined;
  /** Charts with the same id share their hover. The Frame's `syncId` sets it. */
  syncId?: string | undefined;
  /** The plot's height. `medium` (200px) when unsaid. */
  size?: ChartSize | undefined;
  /** A height in pixels when a layout must, in place of `size`. */
  height?: number | undefined;
  /** The number format for the value axis, the tooltip and the labels. The Frame's, else the kit's. */
  format?: Formatter | undefined;
  /** The format for a category. On a time axis the ticks choose their own; this formats the tooltip and the card. */
  formatX?: CategoryFormatter | undefined;
  /** Lines across the plot: a target, a limit, a milestone. */
  reference?: ChartReference[] | undefined;
  /** The plot's accessible name. Unneeded inside a Frame, which names it after its title; a plot with neither is hidden from a screen reader. */
  label?: string | undefined;
  /** Draws the plot's skeleton in place of the marks. The Frame sets it from `status="loading"`. */
  loading?: boolean | undefined;
  /** Called when a point is clicked (anywhere in its column), or Enter chooses the focused one. The selection carries no series: a point is every series at that category. */
  onSelect?: ((selection: ChartSelection) => void) | undefined;
  /** More about the chosen point, in a card anchored to it. The card's head (the category and every series' value) is the kit's. */
  details?: ((selection: ChartSelection) => ReactNode) | undefined;
  className?: string | undefined;
};

export type ChartAreaProps = ChartLineProps & {
  /** Stack the series: parts of a whole over time. */
  stacked?: boolean | undefined;
};

export type ChartScatterProps = {
  data: ChartDatum[];
  /** The key on the horizontal axis. */
  x: string;
  /** The key on the vertical axis. */
  y: string;
  /** A key whose value sizes the point: a bubble. Area, not radius, so twice the value is twice the ink. */
  z?: string | undefined;
  /** The key that names a point in the tooltip. */
  name?: string | undefined;
  /** The key that puts each point in a group, and the groups with their tones. At most three, so any two points stay apart. */
  groupBy?: string | undefined;
  groups?: ChartScatterGroup[] | undefined;
  /** The tone of every point when there are no groups. */
  tone?: ChartTone | undefined;
  /** Lines across the plot: a limit on either axis, or both for quadrants. */
  reference?: ChartReference[] | undefined;
  /** Axis titles, when the keys do not say enough. */
  xLabel?: string | undefined;
  yLabel?: string | undefined;
  size?: ChartSize | undefined;
  height?: number | undefined;
  format?: Formatter | undefined;
  formatX?: CategoryFormatter | undefined;
  label?: string | undefined;
  /** Draws the plot's skeleton in place of the points. The Frame sets it from `status="loading"`. */
  loading?: boolean | undefined;
  /** Called when a point is clicked. */
  onSelect?: ((selection: ScatterSelection) => void) | undefined;
  /** More about the chosen point, in a card anchored to it. The card's head (the point's name, its group and each axis) is the kit's. */
  details?: ((selection: ScatterSelection) => ReactNode) | undefined;
  className?: string | undefined;
};

export type ChartSparklineProps = {
  data: ChartDatum[];
  /** The value key. */
  y: string;
  /** The category key, for the tooltip. Index order when unsaid. */
  x?: string | undefined;
  /** `line` is a stroke; `area` adds a wash; `bars` is a column per point. */
  appearance?: "line" | "area" | "bars" | undefined;
  tone?: ChartTone | undefined;
  /** A dashed hairline at a value: last period, the target. */
  reference?: number | undefined;
  /** A ringed marker on the last point. */
  endDot?: boolean | undefined;
  width?: number | undefined;
  height?: number | undefined;
  /** The number format in the tooltip. */
  format?: Formatter | undefined;
  /** The accessible name: "Open findings, nine months". Unsaid, the sparkline is decoration beside its number. */
  label?: string | undefined;
  /** Draws a skeleton in the sparkline's place. The Frame sets it from `status="loading"`. */
  loading?: boolean | undefined;
  className?: string | undefined;
};

export type ChartTreemapProps = {
  data: TreemapNodeInput[];
  size?: ChartSize | undefined;
  height?: number | undefined;
  format?: Formatter | undefined;
  label?: string | undefined;
  /** Draws the plot's skeleton in place of the tiles. The Frame sets it from `status="loading"`. */
  loading?: boolean | undefined;
  /** Called when a tile is clicked: to drill into its branch, or to filter what is under the chart. */
  onSelect?: ((selection: TreemapSelection) => void) | undefined;
  /** More about the chosen tile, in a card anchored to it. The card's head (the tile, its branch and its value) is the kit's. */
  details?: ((selection: TreemapSelection) => ReactNode) | undefined;
  className?: string | undefined;
};

type TileProps = {
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  name?: string;
  value?: number;
  tone?: ChartTone;
  group?: string;
  depth?: number;
  children?: unknown;
};

export type FilterChipProps = {
  /** The column or the question, as a noun: Owner, Status, Gaps. */
  label: string;
  /** The chosen value, after the label: "Dana Whitfield", "3 chosen". */
  value?: string | undefined;
  /** The filter is applied: solid and selected, and pressed for a screen reader. */
